  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "Ribociclib, which shares the dimethylbenzamide and polar/basic heteroaromatic features of the query, was detected at significant levels in human CSF, demonstrating meaningful CNS access despite physicochemical liabilities.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "AZD3759, a brain-penetrant EGFR inhibitor with an aniline/heteroaromatic core and basic amine, achieved a Kp,uu,brain of 1.3 in preclinical models, showing high unbound brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "A radiolabeled heteroaromatic amide ([11C]DAC) showed rapid, high brain uptake in mice, supporting CNS access for amide-containing heteroaromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A polar amino acid analogue with an ether-linked dichlorobenzyl group showed good brain penetration after oral dosing, indicating that polar/ionizable groups do not preclude CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The brain-penetrating KAT II inhibitor PF-04859989 reduced brain KYNA after systemic administration, confirming functional CNS exposure for an ionizable compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "BINA showed a brain/plasma ratio of 0.75 in vivo, supporting meaningful brain penetration for a compound with polar/aromatic features.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite an unfavorable physicochemical prior, multiple high-transfer experimental analogues with similar amide, heteroaromatic, basic, or polar features demonstrate meaningful CNS access; therefore predict pass.",
